     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict):\n        if str(d.get('all_verified')).lower() == 'true':\n            vars['id_state'] = 'passed'\n            d['what_to_do_next'] = 'Identity is confirmed. Say thank you in one short sentence.'\n        elif d.get('hint') == 'day_month_swapped':\n            d['what_to_do_next'] = 'Ask the customer to say the month of birth as a word. This try does not count.'\n        elif str(d.get('verified')).lower() == 'true':\n            d['what_to_do_next'] = 'Correct. Ask for the last four digits of the phone number on file now.'\n        elif str(d.get('wrong_answers_left')) == '0':\n            vars['id_state'] = 'failed'\n            vars['close_outcome'] = 'not_verified'\n            vars['close_reason'] = 'failed'\n            d['what_to_do_next'] = 'The check failed. Do not mention the account.'\n        elif str(d.get('ok')).lower() == 'false' and not d.get('wrong_answers_left'):\n            d['what_to_do_next'] = 'The answer could not be read. Ask the same question again.'\n        else:\n            d['what_to_do_next'] = 'That answer is wrong. Ask the same question once more.'\n    else:\n        result['what_to_do_next'] = 'The check did not work. Ask the same question again.'\nexcept Exception:\n    pass\n"},
