 "tools": [
  {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0, "alwaysRunsAt": ["end_of_call"]}, "function": {"name": "close_call", "handler": "__function__:api_call", "description": "Record how the call ended.", "parameters": {"type": "object", "properties": {
