        facts = json.loads(vars.get('facts_json') or '[]')
        ref = str(b.get('account_ref') or '')
        vars['pending_ref'] = ref
        f = next((x for x in facts if str(x.get('ref')) == ref), None)
        done = json.loads(vars.get('promised_refs') or '[]')
        v = float(str(b.get('amount_cents')).replace(',', '').strip())
        cents = int(round(v)) if v == int(v) else int(round(v * 100))
        msg = ''
        if f is None:
            msg = 'Unknown account_ref. Use the account_ref from the facts.'
        else:
            if cents < f['floor_cents'] and f['floor_cents'] <= cents * 100 <= f['past_cents']:
                cents = cents * 100
            b['amount_cents'] = cents
            today = datetime.datetime.strptime(str(vars.get('now')).strip().replace(' ', 'T')[:16], '%Y-%m-%dT%H:%M').date()
            dl = datetime.date.fromisoformat(f['deadline'])
