   "on_enter": {"type": "tts", "text": "Thank you. For your security, could you tell me your date of birth?"},
   "on_enter_first_entry_only": true,
   "task_message": "Ask the two security questions one at a time: first the date of birth, then the last four digits of the phone number on file. Call verify_identity after each answer: field date_of_birth with answer as YYYY-MM-DD (a date given only as numbers is day, then month, then year), or field phone_last4 with four digits. If the customer does not want to answer, or asks what the call is about instead, explain once that the questions protect their account. Do not mention the reason for the call.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "verify_identity", "handler": "__function__:api_call", "description": "Check one answer. CALL it every time the customer answers a security question.", "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://bank-mock.invalid/f3-kestrel/v1/verify_identity"},
     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "properties": {
      "customer_id": {"type": "string", "default": "{{customer_id}}"},
      "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "description": "Which question was answered.", "default": "{{field}}"},
      "answer": {"type": "string", "description": "date_of_birth: YYYY-MM-DD. phone_last4: four digits.", "default": "{{answer}}"}},
      "required": ["customer_id", "field", "answer"]}}}},
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict):\n        if str(d.get('all_verified')).lower() == 'true':\n            vars['id_state'] = 'passed'\n            d['what_to_do_next'] = 'Identity is confirmed. Say thank you in one short sentence.'\n        elif d.get('hint') == 'day_month_swapped':\n            d['what_to_do_next'] = 'Ask the customer to say the month of birth as a word. This try does not count.'\n        elif str(d.get('verified')).lower() == 'true':\n            d['what_to_do_next'] = 'Correct. Ask for the last four digits of the phone number on file now.'\n        elif str(d.get('wrong_answers_left')) == '0':\n            vars['id_state'] = 'failed'\n            vars['close_outcome'] = 'not_verified'\n            vars['close_reason'] = 'failed'\n            d['what_to_do_next'] = 'The check failed. Do not mention the account.'\n        elif str(d.get('ok')).lower() == 'false' and not d.get('wrong_answers_left'):\n            d['what_to_do_next'] = 'The answer could not be read. Ask the same question again.'\n        else:\n            d['what_to_do_next'] = 'That answer is wrong. Ask the same question once more.'\n    else:\n        result['what_to_do_next'] = 'The check did not work. Ask the same question again.'\nexcept Exception:\n    pass\n"},
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Hand over to a person. CALL it only when the customer insists on a human after you asked once whether you can help.", "parameters": {"type": "object", "properties": {
