      "queue": {"type": "string", "enum": ["general"], "description": "general: a person.", "default": "general"}},
      "required": ["customer_id", "queue"]}}}},
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'\n    if ok:\n        vars['call_state'] = 'transferred'\n        vars['transfer_reason'] = 'human'\n    if isinstance(d, dict):\n        d['what_to_do_next'] = 'Say a colleague will take over, thank them, say goodbye and call end_call.' if ok else 'The transfer failed. Say so and offer to continue.'\nexcept Exception:\n    pass\n"},
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
