     "code": {"type": "string", "default": "import datetime\nimport json\nHOL = set(datetime.date.fromisoformat(x) for x in ['2026-10-12', '2026-11-11', '2026-11-26', '2026-11-27', '2026-12-25'])\nW = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']\nM = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']\n\ndef bd(d):\n    return d.weekday() < 5 and d not in HOL\n\ndef nbd(d):\n    d = d + datetime.timedelta(days=1)\n    while not bd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef addbd(d, n):\n    for _ in range(n):\n        d = nbd(d)\n    return d\n\ndef lastbd_week(d):\n    mon = d - datetime.timedelta(days=d.weekday())\n    day = mon + datetime.timedelta(days=4)\n    while day >= mon:\n        if bd(day):\n            return day\n        day = day - datetime.timedelta(days=1)\n    return None\n\ndef sp(d):\n    return W[d.weekday()] + ' ' + str(d.day) + ' ' + M[d.month - 1]\n\ndef money(a):\n    return '{:,.2f}'.format(float(a or 0))\n\ndef cents(a):\n    return int(round(float(a or 0) * 100))\n\ndef products(vars):\n    rows = {}\n    for prefix in ('load_account_response.data.products', 'get_account_response.data.products'):\n        start = prefix + '.'\n        for key, value in vars.items():\n            k = str(key)\n            if k.startswith(start):\n                idx, _, field = k[len(start):].partition('.')\n                if idx.isdigit() and field:\n                    rows.setdefault(int(idx), {})[field] = value\n        if rows:\n            break\n    if not rows:\n        raw = vars.get('load_account_response.data.products') or vars.get('products')\n        if isinstance(raw, str):\n            try:\n                raw = json.loads(raw)\n            except ValueError:\n                raw = []\n        if isinstance(raw, list):\n            return [r for r in raw if isinstance(r, dict)]\n    return [rows[i] for i in sorted(rows)]\n\ntry:\n    now = datetime.datetime.strptime(str(vars.get('now')).strip().replace(' ', 'T')[:16], '%Y-%m-%dT%H:%M')\n    today = now.date()\n    lines = []\n    facts = []\n    for n, p in enumerate(products(vars), 1):\n        days = int(float(p.get('days_late') or 0))\n        t = p.get('type')\n        if t == 'credit_card':\n            label = 'credit card ending ' + str(p.get('card_last4') or '')\n            floor = p.get('minimum_payment')\n        elif t == 'car_loan':\n            label = 'car loan'\n            floor = p.get('instalment_amount')\n        else:\n            label = 'personal loan'\n            floor = p.get('instalment_amount')\n        attempts = 1 if days <= 9 else 2\n        deadline = addbd(today, 11 if days <= 9 else 6)\n        wk = lastbd_week(today)\n        if wk is None or wk <= today:\n            wk = lastbd_week(today + datetime.timedelta(days=7))\n        a1 = min(wk, deadline)\n        ref = str(p.get('account_ref'))\n        facts.append(dict(ref=ref, label=label, deadline=deadline.isoformat(), floor_cents=cents(floor), past_cents=cents(p.get('past_due'))))\n        s = str(n) + '. ' + label + ' (account_ref ' + ref + '): past due ' + money(p.get('past_due')) + ' (amount_cents ' + str(cents(p.get('past_due'))) + '), ' + str(days) + ' days late. Floor (lowest amount): ' + money(floor) + ' (amount_cents ' + str(cents(floor)) + '). Latest date (deadline): ' + sp(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts: ' + str(attempts) + '. Attempt 1: the full past due (or the floor if they already said the full amount is too much) on ' + sp(a1) + ' (' + a1.isoformat() + ').'\n        if attempts == 2:\n            s += ' Attempt 2: the floor ' + money(floor) + ' on ' + sp(deadline) + ' (' + deadline.isoformat() + ').'\n        lines.append(s)\n    mon = today - datetime.timedelta(days=today.weekday())\n    wk = lambda m: ', '.join(W[i] + ' ' + (m + datetime.timedelta(days=i)).isoformat() + ('' if bd(m + datetime.timedelta(days=i)) else ' (not a business day)') for i in range(7))\n    lines.append('This week (\"this <weekday>\"): ' + wk(mon) + '.')\n    lines.append('Next week (\"next <weekday>\"): ' + wk(mon + datetime.timedelta(days=7)) + '.')\n    lines.append('Week after: ' + wk(mon + datetime.timedelta(days=14)) + '.')\n    vars['facts_text'] = 'Today is ' + sp(today) + ' (' + today.isoformat() + '). Today is ' + ('' if bd(today) else 'not ') + 'a business day. Business days are Monday to Friday except 12 October, 11 November, 26 and 27 November and 25 December 2026.\\n' + '\\n'.join(lines)\n    vars['facts_json'] = json.dumps(facts)\n    vars['product_count'] = str(len(facts))\n    vars['call_state'] = 'verified'\n    vars['close_outcome'] = 'no_promise'\n    vars['close_reason'] = 'refused'\n    vars['facts_state'] = 'ok' if facts else 'empty'\nexcept Exception:\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['facts_json'] = '[]'\n    vars['facts_state'] = 'error'\n"},
